<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIntegration} from '../../stores/integration'
import {useDetection} from '../../composables/useDetection'
import {allPages,errorText,localApi} from '../../services/local/api'
import {submissionDone,submissionKey} from '../../services/local/submission'
import {exportLocalReport,localReportText} from '../../services/local/report'
import {eventIdsFromQuery,taskLabel} from '../../services/local/fields'
import type {Diagnosis,Report} from '../../services/local/types'
import Panel from '../../components/Panel.vue'
import ServiceState from '../../components/local/ServiceState.vue'
import LocalChart from '../../components/local/LocalChart.vue'
import {time} from '../../utils'
const route=useRoute(),router=useRouter(),service=useIntegration(),diagnosis=ref<Diagnosis>(),report=ref<Report>(),selected=ref<string[]>([]),note=ref(''),error=ref(''),busy=ref(false),exporting=ref(false),diagnosisHistory=ref<Diagnosis[]>([]),reports=ref<Report[]>([]),historyError=ref(''),historyPage=ref(1),reportPage=ref(1),archiveFilter=ref('all'),chart=ref<InstanceType<typeof LocalChart>>(),draftDate=ref(new Date().toISOString())
const sourceId=computed(()=>report.value?.detectionId??String(route.query.detectionId??diagnosis.value?.detectionId??'')),resource=useDetection(sourceId)
const task=computed(()=>report.value?.snapshot.task??resource.task.value),result=computed(()=>report.value?.snapshot.result??resource.result.value),events=computed(()=>report.value?.snapshot.events??resource.events.value),points=computed(()=>report.value?.snapshot.points??resource.points.value)
const canDiagnose=computed(()=>!!service.runtime?.capabilities.causeDiagnosis),canStore=computed(()=>!!service.runtime?.capabilities.reportPersistence),eventSet=computed(()=>events.value.filter(e=>selected.value.includes(e.id)))
const matchingDiagnosis=computed(()=>diagnosis.value?.status==='success'&&diagnosis.value.detectionId===task.value?.id&&JSON.stringify([...diagnosis.value.eventIds].sort())===JSON.stringify([...selected.value].sort())?diagnosis.value:null)
const current=computed<Report|undefined>(()=>{if(report.value)return {...report.value,note:note.value};if(!task.value||!result.value)return undefined;return {id:`LOCAL-${task.value.id}`,title:'换热站运行状态异常检测报告',detectionId:task.value.id,diagnosisId:matchingDiagnosis.value?.id??null,eventIds:[...selected.value],version:0,revision:0,createdAt:draftDate.value,archivedAt:null,note:note.value,snapshot:{task:task.value,result:result.value,events:eventSet.value,points:points.value,diagnosis:matchingDiagnosis.value}}})
const sections=computed(()=>current.value?localReportText(current.value):[]),filteredReports=computed(()=>reports.value.filter(r=>archiveFilter.value==='all'||(archiveFilter.value==='archived'?!!r.archivedAt:!r.archivedAt))),series=computed(()=>[{name:'异常分数',unit:'分数',color:'#2563eb',data:points.value.map(p=>[p.timestamp,p.score] as [string,number])},{name:'阈值',unit:'分数',color:'#c2410c',data:points.value.map(p=>[p.timestamp,p.threshold] as [string,number])}])
let controller:AbortController|undefined,historyController:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,generation=0,loadedRoute=''
watch(archiveFilter,()=>reportPage.value=1)
watch([()=>route.query.reportId,()=>route.query.diagnosisId,()=>route.params.id,()=>route.query.detectionId,()=>route.query.eventIds,()=>service.ready],async()=>{
 const run=++generation;controller?.abort();clearTimeout(timer);controller=new AbortController();const c=controller
 if(!service.ready)return
 const routeKey=JSON.stringify([route.query.reportId,route.query.diagnosisId,route.params.id,route.query.detectionId,route.query.eventIds]),preserve=loadedRoute===routeKey;loadedRoute=routeKey
 if(!preserve){diagnosis.value=undefined;report.value=undefined;note.value='';selected.value=eventIdsFromQuery(route.query.eventIds);draftDate.value=new Date().toISOString()}else if(report.value&&note.value!==report.value.note)return
 error.value=''
 async function readDiagnosis(id:string){try{const d=await localApi.diagnosis(id,c.signal);if(run!==generation)return;if(route.query.detectionId&&d.detectionId!==String(route.query.detectionId))throw new Error('诊断与来源检测不一致，已停止展示。');diagnosis.value=d;if(d.status==='running'||d.status==='queued')timer=setTimeout(()=>readDiagnosis(id),document.hidden?5000:1000)}catch(e){if(!c.signal.aborted&&run===generation){error.value=errorText(e)}}}
 try{if(route.query.reportId){if(!canStore.value)throw new Error('本机后端尚未启用报告存档。');const r=await localApi.report(String(route.query.reportId));if(run!==generation)return;report.value=r;note.value=r.note;selected.value=[...r.eventIds];diagnosis.value=r.snapshot.diagnosis??undefined}
 else {const id=String(route.query.diagnosisId??route.params.id??'');if(id){if(!canDiagnose.value)throw new Error('本机后端尚未启用原因诊断。');await readDiagnosis(id)}}}catch(e){if(!c.signal.aborted)error.value=errorText(e)}
},{immediate:true})
watch(events,rows=>{if(!rows.length)return;selected.value=selected.value.filter(id=>rows.some(e=>e.id===id))})
async function loadHistory(){historyController?.abort();historyController=new AbortController();const c=historyController;historyError.value='';if(!service.ready)return
 try{const [d,r]=await Promise.all([canDiagnose.value?allPages(p=>localApi.diagnoses(p,c.signal)):Promise.resolve([]),canStore.value?allPages(p=>localApi.reports(p,c.signal)):Promise.resolve([])]);if(!c.signal.aborted){diagnosisHistory.value=d;reports.value=r}}catch(e){if(!c.signal.aborted)historyError.value=errorText(e)}}
watch([()=>service.ready,()=>service.revision],loadHistory,{immediate:true})
async function analyze(){if(!task.value||!selected.value.length||busy.value||!canDiagnose.value)return;busy.value=true;error.value='';try{const body={detectionId:task.value.id,eventIds:[...selected.value]};const d=await localApi.createDiagnosis(body.detectionId,body.eventIds,submissionKey('diagnosis',body));submissionDone('diagnosis');await router.push({path:'/diagnosis/'+encodeURIComponent(d.id),query:{detectionId:body.detectionId,eventIds:JSON.stringify(body.eventIds)}});await loadHistory()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function save(){if(!current.value||!canStore.value)throw new Error('报告存档能力未启用。');if(report.value){const saved=await localApi.note(report.value.id,note.value,report.value.revision);report.value=saved;return saved}
 const body={detectionId:current.value.detectionId,eventIds:[...selected.value],diagnosisId:matchingDiagnosis.value?.id??null};let saved=await localApi.createReport(body.detectionId,body.eventIds,body.diagnosisId,submissionKey('report',body));submissionDone('report');report.value=saved
 if(note.value!==saved.note){saved=await localApi.note(saved.id,note.value,saved.revision);report.value=saved}await loadHistory();return saved
}
async function mutate(action:'save'|'archive'|'version'){if(busy.value||exporting.value)return;busy.value=true;error.value='';try{if(action==='version'&&report.value){const r=await localApi.version(report.value.id,report.value.revision);await router.push({path:'/diagnosis',query:{reportId:r.id}})}else{const r=await save();if(action==='archive'){report.value=await localApi.archive(r.id,r.revision)}note.value=report.value!.note}await loadHistory()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function exportFile(format:'docx'|'pdf'){if(!current.value||exporting.value||busy.value)return;exporting.value=true;error.value='';try{let snapshot=current.value;if(report.value&&!report.value.archivedAt&&note.value!==report.value.note)snapshot=await save();await exportLocalReport(snapshot,format,chart.value?.image()??'')}catch(e){error.value=errorText(e)}finally{exporting.value=false}}
function chooseAll(event:globalThis.Event){selected.value=(event.target as HTMLInputElement).checked?events.value.map(e=>e.id):[]}
onBeforeUnmount(()=>{generation++;controller?.abort();historyController?.abort();clearTimeout(timer)})
</script>
<template><div class="page-stack local-page"><div class="page-actions"><div><h2>AI诊断</h2><p class="muted">数值异常是观测结果；具体原因和解决建议需要独立的诊断能力。</p></div><RouterLink :to="sourceId?'/detections/'+encodeURIComponent(sourceId):'/detections'">返回数据监测</RouterLink></div><ServiceState><p v-if="!canDiagnose" class="local-notice">原因诊断尚未接入。可核查所选异常与实际分数曲线，并导出阶段性检测报告。</p><p v-if="error||resource.error.value" class="error" role="alert">{{error||resource.error.value}}</p><p v-if="resource.loading.value" role="status">正在读取来源任务…</p><template v-if="task&&result"><Panel title="来源与异常事件选择"><p class="local-source">{{task.contextSnapshot.enterprise.name}} / {{task.contextSnapshot.network.name}} / {{task.contextSnapshot.segment.name}} / {{task.contextSnapshot.station.name}}</p><p>来源检测 {{task.id}} · {{taskLabel[task.status]}} · {{task.modelSnapshot.isDemo?'示例模型':'本站登记模型'}} {{task.modelSnapshot.version}}</p><div class="local-actions"><label><input type="checkbox" :checked="!!events.length&&selected.length===events.length" :disabled="!!report||busy" @change="chooseAll"/>全选 {{events.length}} 项</label><button class="primary" :disabled="!canDiagnose||!selected.length||busy||!!report||diagnosis?.status==='running'||diagnosis?.status==='queued'" @click="analyze">{{busy?'提交中…':'分析所选 '+selected.length+' 项异常'}}</button></div><label v-for="e in events" :key="e.id" class="local-event-choice"><input v-model="selected" type="checkbox" :value="e.id" :aria-label="'诊断选择 '+e.id" :disabled="!!report||busy"/><span><strong>{{e.title}}</strong><small>{{e.id}} · {{time(e.start)}} — {{time(e.end)}}</small><small>峰值分数 {{e.peak_score}} · 原因尚需核查</small></span></label><p v-if="!events.length" class="empty">本次检测没有确认告警，不需要创建原因诊断。</p><LocalChart ref="chart" :series="series" :events="eventSet"/></Panel><Panel v-if="diagnosis" title="实际分析过程与结果"><p>{{taskLabel[diagnosis.status]}} · {{({queued:'等待执行',completed:'处理完成',failed:'处理失败'} as Record<string,string>)[diagnosis.phase]??diagnosis.phase}}</p><p v-if="diagnosis.error" class="error" role="alert">{{diagnosis.error.message}}。保留原记录，可重新选择事件创建诊断。</p><section v-for="(step,i) in diagnosis.steps" :key="i" class="local-evidence"><h3>{{step.title}} · {{({pending:'待执行',running:'执行中',done:'已完成',failed:'失败'})[step.state]}}</h3><p>{{step.summary}}</p><ul><li v-for="(text,j) in step.evidence" :key="j">{{text}}</li></ul></section><p v-if="diagnosis.status==='running'||diagnosis.status==='queued'" role="status">等待实际分析步骤，不生成模拟思考或进度。</p><p v-if="diagnosis.status==='failed'"><button :disabled="busy" @click="analyze">以所选事件新建诊断</button></p></Panel><Panel title="报告预览与导出"><template #tools><span class="badge orange">{{report?'V'+report.version+' · '+(report.archivedAt?'已归档':'已保存'):'临时报告 · 未存档'}}</span></template><p v-if="!canStore" class="muted">后端尚未启用报告持久化。备注仅保留在当前页面，可随 Word/PDF 导出；不会提示已归档。</p><p v-else-if="!report" class="muted">保存后，报告版本与所选事件将固定；历史报告可创建新版本。</p><div v-for="section in sections" :key="section.heading" class="local-report-section"><h3>{{section.heading}}</h3><p v-for="(line,i) in section.lines" :key="i">{{line}}</p></div><label>报告备注<textarea v-model="note" rows="4" maxlength="4000" aria-label="本机报告备注" :disabled="!!report?.archivedAt||busy||exporting"/></label><div class="local-actions mt"><button :disabled="!canStore||busy||exporting||!!report?.archivedAt||!selected.length" @click="mutate('save')">保存报告与备注</button><button :disabled="!canStore||busy||exporting||!!report?.archivedAt||!selected.length" @click="mutate('archive')">保存并归档</button><button v-if="report" :disabled="!canStore||busy||exporting" @click="mutate('version')">创建新版本</button><button class="primary" :disabled="exporting||busy||!selected.length" @click="exportFile('docx')">{{exporting?'导出中…':'导出 Word'}}</button><button class="primary" :disabled="exporting||busy||!selected.length" @click="exportFile('pdf')">导出 PDF</button></div></Panel></template><p v-else-if="!sourceId" class="empty">请从数据监测单选或多选确认告警事件，或打开下面的历史记录。</p><Panel title="诊断历史与报告归档"><template #tools><button @click="loadHistory">刷新历史</button></template><p v-if="historyError" class="error" role="alert">{{historyError}}</p><div class="table-wrap"><table><thead><tr><th>诊断</th><th>来源检测</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in diagnosisHistory.slice((historyPage-1)*20,historyPage*20)" :key="d.id"><td>{{d.id}}</td><td>{{d.detectionId}}</td><td>{{taskLabel[d.status]}}</td><td><RouterLink :to="{path:'/diagnosis/'+encodeURIComponent(d.id),query:{detectionId:d.detectionId,eventIds:JSON.stringify(d.eventIds)}}">查看诊断</RouterLink></td></tr><tr v-if="!diagnosisHistory.length"><td colspan="4" class="empty">{{canDiagnose?'暂无真实诊断历史':'后端尚未启用原因诊断'}}</td></tr></tbody></table></div><div class="pagination"><span>第 {{historyPage}} 页</span><button :disabled="historyPage===1" @click="historyPage--">上一页</button><button :disabled="historyPage*20>=diagnosisHistory.length" @click="historyPage++">下一页</button></div><label>归档状态<select v-model="archiveFilter" aria-label="本机报告归档状态"><option value="all">全部报告</option><option value="archived">已归档</option><option value="draft">未归档</option></select></label><div class="table-wrap"><table><thead><tr><th>报告</th><th>版本</th><th>存档状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in filteredReports.slice((reportPage-1)*20,reportPage*20)" :key="r.id"><td>{{r.title}}</td><td>{{r.version}}</td><td>{{r.archivedAt?'已归档':'未归档'}}</td><td><RouterLink :to="{path:'/diagnosis',query:{reportId:r.id}}">查看报告</RouterLink></td></tr><tr v-if="!filteredReports.length"><td colspan="4" class="empty">{{canStore?'暂无已保存报告':'后端尚未启用本机报告存档'}}</td></tr></tbody></table></div><div class="pagination"><span>{{filteredReports.length}} 条 · 第 {{reportPage}} 页</span><button :disabled="reportPage===1" @click="reportPage--">上一页</button><button :disabled="reportPage*20>=filteredReports.length" @click="reportPage++">下一页</button></div></Panel></ServiceState></div></template>
